function drawCardSigil(card,x,y,size,color){const seed=String(card.id||card.cardId||card.name||"").split("").reduce((sum,char)=>sum+char.charCodeAt(0),0),variant=seed%4;ctx.save();ctx.strokeStyle=color;ctx.fillStyle=color;ctx.lineWidth=Math.max(1.5,size*.08);ctx.globalAlpha=.95;if(variant===0){drawStar(x,y,size*.48,size*.15,color);ctx.beginPath();ctx.arc(x,y,size*.34,0,Math.PI*2);ctx.stroke();}else if(variant===1){ctx.beginPath();ctx.ellipse(x,y,size*.5,size*.2,-.45,0,Math.PI*2);ctx.stroke();ctx.beginPath();ctx.ellipse(x,y,size*.5,size*.2,.45,0,Math.PI*2);ctx.stroke();ctx.beginPath();ctx.arc(x,y,size*.12,0,Math.PI*2);ctx.fill();}else if(variant===2){ctx.beginPath();ctx.moveTo(x,y-size*.48);ctx.lineTo(x+size*.42,y+size*.28);ctx.lineTo(x-size*.42,y+size*.28);ctx.closePath();ctx.stroke();drawStar(x,y+size*.05,size*.22,size*.07,color);}else{ctx.beginPath();for(let index=0;index<6;index++){const angle=-Math.PI/2+index*Math.PI/3,px=x+Math.cos(angle)*size*.44,py=y+Math.sin(angle)*size*.44;if(index)ctx.lineTo(px,py);else ctx.moveTo(px,py);}ctx.closePath();ctx.stroke();ctx.beginPath();ctx.arc(x,y,size*.16,0,Math.PI*2);ctx.fill();}ctx.restore();}
function button(id,x,y,w,h,title,sub,enabled,data){box(x,y,w,h,10,enabled?gradient(y,h,"#6756a8","#30295d"):"#242940",enabled?"#8978ca":"#454b64");text(title,x+w/2,y+(sub?h*.38:h/2),sub?15:13,enabled?"#fff":"#707891","center",700);if(sub)text(sub,x+w/2,y+h*.72,10,enabled?"#d7d7ec":"#646a82","center");if(enabled)hit(id,x,y,w,h,data);}
function clippedHit(id,x,y,w,h,data,clipTop,clipBottom){const top=Math.max(y,clipTop),bottom=Math.min(y+h,clipBottom);if(bottom>top)hit(id,x,top,w,bottom-top,data);}
function clippedButton(id,x,y,w,h,title,sub,enabled,data,clipTop,clipBottom){const hitCount=state.hit.length;button(id,x,y,w,h,title,sub,enabled,data);if(state.hit.length===hitCount)return;const target=state.hit[state.hit.length-1],top=Math.max(y,clipTop),bottom=Math.min(y+h,clipBottom);if(bottom<=top)state.hit.pop();else{target.y=top;target.h=bottom-top;}}
function inventory(cardId){return(state.player.inventory||[]).find(item=>item.cardId===cardId)||{normalCount:0,shinyCount:0};}
function ownedCount(){return(state.player.inventory||[]).reduce((sum,item)=>sum+item.normalCount+item.shinyCount,0);}
function cloudError(error){const raw=String(error&&error.message||error||"云端请求失败").replace(/^Error:\s*/,"");const business=raw.match(/errMsg:\s*Error:\s*([\s\S]+?)(?:\s+at\s+\/|$)/);return business?business[1].trim():raw;}
function notifyError(message){const msg=String(message||"").replace(/^\s+|\s+$/g,"").slice(0,60);if(!msg)return;state.error="";if(state.screen==="battle"&&state.battle){state.battleNotice=msg;state.battleNoticeUntil=Date.now()+2600;render();setTimeout(()=>{if(Date.now()>=state.battleNoticeUntil&&state.battleNotice===msg){state.battleNotice="";render();}},2680);return;}wx.showToast({title:msg,icon:"none",duration:2400});}
function resyncBattle(){return api.battleStatus().then(result=>{const game=result&&result.game;if(!game)return null;state.battle=game;state.battleConfirmed=cloneBattle(game);state.mulliganSelected=[];state.battleQueue=[];state.battlePending=0;state.battleAiThinking=false;state.battleAiAction="";render();return game;}).catch(()=>null);}
function syncServices(result){if(!result)return;if(result.player)state.player=result.player;if(result.shop)state.shop=result.shop;if(result.mail)state.mail=result.mail;if(result.tasks)state.tasks=result.tasks;if(result.redDots)state.redDots=result.redDots;}
function call(task,success){state.loading=true;state.error="";render();return task.then(result=>{if(result.player)state.player=result.player;if(success)success(result);return api.loadServices().then(service=>syncServices(service)).catch(error=>{console.warn("操作成功，但刷新服务面板失败",error);}).then(()=>result);}).catch(error=>{state.error=cloudError(error);notifyError(state.error);return null;}).finally(()=>{state.loading=false;render();});}
function direct(task,success){state.loading=true;state.error="";render();return task.then(result=>{if(success)success(result);return result;}).catch(error=>{state.error=cloudError(error);notifyError(state.error);return null;}).finally(()=>{state.loading=false;render();});}

function refresh(showSign){state.loading=true;state.configReady=false;state.error="";return api.initCloud().then(()=>api.loadGameData()).then(result=>{state.player=result.player;state.cards=result.cards;loadCardArt(state.cards);state.sets=result.sets;state.pools=result.pools;state.config=result.config;state.signStatus=result.signStatus;state.userKey=result.userKey;state.balanceNotices=result.balanceNotices||{status:"ready",latest:null,items:[]};state.hasUnreadBalanceNotice=Boolean(result.hasUnreadBalanceNotice);return api.loadServices();}).then(service=>{syncServices(service);state.configReady=true;state.hasLoaded=true;if(showSign&&state.signStatus&&!state.signStatus.claimedToday)state.showSign=true;}).catch(error=>{state.error=cloudError(error);}).finally(()=>{state.loading=false;render();});}

