function rewardsLabel(rewards){return(rewards||[]).map(reward=>{if(reward.type==="coin")return`${reward.amount}金币`;if(reward.type==="ticket")return`${reward.amount}券`;if(reward.type==="dust")return`${reward.amount}星尘`;if(reward.type==="randomCard")return`随机${RARITY_LABEL[reward.rarity]}卡×${reward.amount||1}`;if(reward.type==="card")return`${reward.name||reward.cardId}×${reward.amount||1}`;return reward.type;}).join(" · ");}
function drawRedDot(x,y){ctx.fillStyle="#ff566d";ctx.beginPath();ctx.arc(x,y,5,0,Math.PI*2);ctx.fill();}
function noticeDate(value){const timestamp=Number(value||0);if(!Number.isFinite(timestamp)||timestamp<=0)return"日期未设置";return new Date(timestamp+8*3600000).toISOString().slice(0,10);}
function noticeKeywords(snapshot){const items=(snapshot&&snapshot.keywords||[]).map(item=>KEYWORD_LABEL[item]||item);return items.length?items.join("、"):"无";}
function noticeValue(snapshot,key){if(key==="keywords")return noticeKeywords(snapshot);if(key==="rulesText")return String(snapshot&&snapshot.rulesText||"无");return String(snapshot&&snapshot[key]!=null?snapshot[key]:0);}
