function resetCollectionState(){state.collectionSearch="";state.collectionFilters={sets:[],rarities:[],costs:[],versions:[]};state.collectionFilter="all";state.showCollectionFilters=false;state.scrollY=0;}
function collectionSearchText(card){return[card.name,card.id,card.rulesText,card.description,(card.keywords||[]).join(" "),(card.keywords||[]).map(item=>KEYWORD_LABEL[item]||item).join(" ")].filter(Boolean).join(" ").toLowerCase();}
function collectionMatches(card){return matchesCollectionCard(card,state.collectionFilters,state.collectionSearch);}
function matchesCollectionCard(card,filters,searchValue){const search=String(searchValue||"").trim().toLowerCase();if(search&&!collectionSearchText(card).includes(search))return false;if(filters.sets.length&&!filters.sets.includes(card.set))return false;if(filters.rarities.length&&!filters.rarities.includes(card.rarity))return false;if(filters.costs.length&&!filters.costs.includes(Number(card.cost)))return false;return true;}
function filteredCards(){return state.cards.filter(collectionMatches);}
function collectionFilterOptions(){return{sets:state.sets.map(item=>({value:item.id,label:item.name})),rarities:RARITIES.map(item=>({value:item,label:RARITY_LABEL[item]})),costs:[...new Set(state.cards.map(card=>Number(card.cost)).filter(Number.isFinite))].sort((a,b)=>a-b).map(value=>({value,label:`${value}费`})),versions:[{value:"normal",label:"普通卡"},{value:"shiny",label:"闪卡"}]};}
function collectionVersionMatches(card,versions){return !versions.length||versions.includes(card.shiny?"shiny":"normal");}
function toggleCollectionFilter(group,value){const list=state.collectionFilters[group]||[],index=list.indexOf(value);if(index>=0)list.splice(index,1);else list.push(value);state.scrollY=0;render();}
function clearCollectionFilters(){state.collectionSearch="";state.collectionFilters={sets:[],rarities:[],costs:[],versions:[]};state.scrollY=0;render();}
function openCollectionSearch(){wx.showModal({title:"搜索卡牌",editable:true,placeholderText:"名称、ID、规则或关键词",content:state.collectionSearch,success:result=>{if(!result.confirm)return;state.collectionSearch=String(result.content||"").trim();state.scrollY=0;render();}});}
