function renderCollection(){serviceBg();const cards=filteredCards(),owned=cards.filter(card=>{const e=inventory(card.id);return e.normalCount+e.shinyCount>0;}).length,top=header("星界卡牌图鉴",`已收集 ${owned} / ${state.cards.length} 种`),m=12,searchW=W-2*m-78;box(m,top,searchW,36,10,"#1b2345dd","#586694");text(state.collectionSearch||"搜索名称 / ID / 规则 / 关键词",m+12,top+18,10,state.collectionSearch?"#fff":"#8f99bc","left");hit("collectionSearch",m,top,searchW,36);button("collectionFilters",W-m-70,top,70,36,"筛选","",true);const start=top+46,allEntries=cards.flatMap(card=>[{card:{...card,shiny:false},label:"普通",count:inventory(card.id).normalCount},{card:{...card,shiny:true},label:"闪卡",count:inventory(card.id).shinyCount}]),entries=allEntries.filter(entry=>collectionVersionMatches(entry.card,state.collectionFilters.versions)),cols=3,gap=7,cw=(W-m*2-gap*(cols-1))/cols,cardH=cw*1.5,countH=20,rowH=cardH+countH,rows=Math.ceil(entries.length/cols);state.maxScroll=Math.max(0,rows*(rowH+gap)-(H-start-safeBottom));ctx.save();ctx.beginPath();ctx.rect(0,start,W,H-start-safeBottom);ctx.clip();entries.forEach((entry,i)=>{const x=m+(i%cols)*(cw+gap),y=start+Math.floor(i/cols)*(rowH+gap)-state.scrollY;if(y+rowH<start||y>H)return;ctx.globalAlpha=entry.count>0?1:.42;miniCard(entry.card,x,y,cw,cardH,{transparentOuter:true});ctx.globalAlpha=1;text(`${entry.label} ${entry.count}`,x+cw/2,y+cardH+11,8,entry.card.shiny?"#ffe39a":"#d1d6e9","center");clippedCardHit(entry.card,x,y,cw,cardH,0,start,W,H-safeBottom);});if(!entries.length)text("没有匹配的卡牌",W/2,start+70,13,"#d1d6e9","center");ctx.restore();scrollBar(start);}

